package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Saves the claim's changes; refuses them unless the claim is a DRAFT (an open claim is voided and added anew
 * instead), when its date, or the one it would move to, is in a closed period, and when it would move after its
 * person's retirement date, and a correction that does not name a settled claim of its person. */
public class ApplyClaim {
    public void apply(@Val ClaimInput input, @Val Sheet sheet, @Val Claim claim, ClaimRepository repository,
            PeriodRepository periods, PersonRepository people) throws InvalidClaimException {
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new InvalidClaimException("Only a draft claim can be edited; void it and add a new one.");
        }
        LocalDate date = input.date() != null ? input.date() : sheet.getToday();
        if (periods.isClosedOn(sheet.getId(), claim.getDate()) || periods.isClosedOn(sheet.getId(), date)) {
            throw new InvalidClaimException("No claim can be edited in a closed period.");
        }
        if (people.findById(claim.getPersonId()).map(p -> p.retiredOn(date)).orElse(false)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date.");
        }
        repository.checkCorrects(sheet.getId(), claim.getPersonId(), input.corrects());
        claim.setAmount(input.amount());
        claim.setCorrects(input.corrects());
        claim.setDate(date);
        claim.setNote(input.note());
        repository.saveAndFlush(claim);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds the claim; refuses one dated in a closed period, or after the person's retirement date, and a correction
 * that does not name a settled claim of the person. */
public class BuildClaim {
    public void build(@Val ClaimInput input, @Val Sheet sheet, @Val Person person, ClaimRepository repository,
            PeriodRepository periods, Out<Claim> claimOut) throws InvalidClaimException {
        LocalDate date = input.date() != null ? input.date() : sheet.getToday();
        if (periods.isClosedOn(sheet.getId(), date)) {
            throw new InvalidClaimException("No claim can be added in a closed period.");
        }
        if (person.retiredOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date.");
        }
        repository.checkCorrects(sheet.getId(), person.getId(), input.corrects());
        claimOut.set(repository.save(new Claim(sheet.getId(), person.getId(), input.amount(), date, input.note(),
                input.corrects())));
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status: it starts DRAFT, is opened (OPEN) and then settled (SETTLED); a DRAFT or OPEN claim
 * can be voided (VOID). SETTLED and VOID are final. Only OPEN and SETTLED claims count toward totals.
 */
public enum ClaimStatus {
    DRAFT, OPEN, SETTLED, VOID;

    /** The status an action ("open", "settle", "void") moves this one to, or null when it is not allowed. */
    public ClaimStatus after(String action) {
        return switch (action) {
            case "open" -> this == DRAFT ? OPEN : null;
